    <div id="CreateObjectView">
      <button id="create-button" onClick={() => {
        if (value) {
          model.createObject(value).then()
          model.setSelectedAsset(value)
        }
      }}>
        Add Object
      </button>
      <div id="assets-container">
        <label htmlFor="asset-select">Asset:</label>
        <select id="asset-select" value={value} onChange={e => setValue(e.target.value)}>
          <option value="" disabled selected hidden>Select an asset</option>
          {model.availableAssets.map(asset => (
            <option key={asset.id} id={`asset-option-${asset.id}`} value={asset.id}>
              {asset.name}
            </option>
          ))}
        </select>
      </div>
      <button id="cleanup-button" onClick={() => model.cleanupScene()}>Cleanup scene</button>
    </div>
  )
})
