  // Initialize empty arrays for adjectives and other words
  const adjectives = [];
  const otherWords = [];

  // Iterate through each word in the sentence
  for (const word of words) {
    // Determine if the word is an adjective using a dictionary or a part-of-speech tagger
    if (isAdjective(word)) {
      adjectives.unshift(word);
    } else {
      otherWords.push(word);
    }
  }

  // Combine the reversed adjectives and other words to form the new sentence
  return otherWords.join(' ') + ' ' + adjectives.join(' ') + ' ';
}

