```javascript
function reverseAdjectiveOrder(sentence) {
  // Split the sentence into words
  const words = sentence.split(' ');

  // Initialize empty arrays for adjectives and other words
  const adjectives = [];
  const otherWords = [];

  // Iterate through each word and determine if it's an adjective
  for (let i = 0; i < words.length; i++) {
    const word = words[i];

    // Use a list of common English adjectives to check if the word is an adjective
    const isAdjective = new RegExp(/^([A-Z][a-z]*[a-z]+[ ]*(j|qu|en|abl|an|ant|as|at|but|by|for|from|in|into|of|on|per|to|up|via)[ ]*[A-Z][a-z]*[a-z]+)$/).test(word);

    if (isAdjective) {
      adjectives.unshift(word);
    } else {
      otherWords.push(word);
    }
  }

  // Combine the reversed adjectives and other words to form the new sentence
  return otherWords.concat(adjectives.slice(1)).join(' ') + ' ' + words[words.length - 1];
}

