function sortJsonByKeys(jsonObj) {
  // Convert JSON object to array of key-value pairs using Object.entries()
  const entries = Object.entries(jsonObj);

  // Sort the array of key-value pairs using Array.prototype.sort() and a compare function
  entries.sort((a, b) => {
    // Use localeCompare for case insensitive comparison or use toString() and compare strings for exact match
    return a[0].toString().localeCompare(b[0]);
  });

  // Extract sorted keys and rebuild the JSON object
  const sortedKeys = entries.map((entry) => entry[0]);
  const sortedValues = entries.map((entry) => entry[1]);

  return Object.fromEntries(sortedKeys.map((key, index) => [key, sortedValues[index]]));
}

