void sortJsonArray(const std::string& jsonStr) {
    json j = json::parse(jsonStr);
    std::vector<int> arr = j["array"].get<std::vector<int>>();
    bubbleSort(arr);
    std::cout << json({{"sortedArray", arr}}) << std::endl;
}

int main() {
    std::string jsonStr = R"({
      "array": [5, 2, 9, 1, 5, 6]
    })";
    sortJsonArray(jsonStr);
    return 0;
}
```

This program uses the nlohmann/json library to parse the JSON string and extract the array to be sorted. The parsed JSON is then passed to the `bubbleSort` function, which sorts the vector, and finally, the sorted array is returned as part of a new JSON object.

