```csharp
using System;
using System.Net.Http;
using System.Text;
using Newtonsoft.Json;

public class RestServiceWrapper
{
    private readonly string _baseAddress;
    private readonly HttpClient _client;
    private string _accessToken;

    public RestServiceWrapper(string baseAddress)
    {
        _baseAddress = baseAddress;
        _client = new HttpClient();
    }

    public void SetAccessToken(string accessToken)
    {
        _accessToken = accessToken;
        _client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _accessToken);
    }

    public async Task<T> GetAsync<T>(string requestUri)
    {
        using (var response = await _client.GetAsync($"{_baseAddress}/{requestUri}")))
        {
            response.EnsureSuccessStatusCode();
            var content = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<T>(content);
        }
    }

    public async Task<T> PostAsync<T>(string requestUri, object data)
    {
        var json = JsonConvert.SerializeObject(data);
        using (var stringContent = new StringContent(json, Encoding.UTF8, "application/json"))
        {
            using (var response = await _client.PostAsync($"{_baseAddress}/{requestUri}", stringContent))
            {
                response.EnsureSuccessStatusCode();
                var content = await response.Content.ReadAsStringAsync();
                return JsonConvert.DeserializeObject<T>(content);
            }
        }
    }
}
```

This wrapper class has methods to set the access token, send GET and POST requests, and automatically handles JSON deserialization. Make sure you install the `Newtonsoft.Json` NuGet package if you don't already have it.

