 Here's an example of creating a professional access permissions guard using middleware in Nest.js with TypeORM for handling user roles and their associated permissions:

```javascript
// Import required modules
const { Injectable, CanActivate, ExecutionContext, ForbiddenException } = require('@nestjs/common');
import { Repository } from 'typeorm';
import { UserRole } from './user-role.entity'; // Assuming you have a UserRole entity
import { UsersService } from '../users/users.service'; // Assuming you have a UsersService

@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private usersService: UsersService, private roleRepository: Repository<UserRole>) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const user = await this.usersService.findOneByUsername(request.username);

    if (!user) throw new UnauthorizedException();

    const roles = user.roles.map((role) => role.name);

    const routeHandler = (req: Request, res: Response, next: NextFunction) => next();
    const handler = this.extractRolesFromRoute(routeHandler);

    return this.checkUserHasPermission(roles, handler.requiredRoles);
  }

  extractRolesFromRoute(handler: Function): { requiredRoles: string[] } {
    const handlers = (handler as any).prototype;
    const decorators = Reflect.getMetadataKeys(handlers, Reflect.MetadataKeys.DESCRIBER);

    if (decorators.includes('roles')) {
      return {
        requiredRoles: decorators.filter(key => key === 'roles')[0].data,
      };
    }

    return {};
  }

  checkUserHasPermission(userRoles: string[], requiredRoles: string[]) {
    return userRoles.some((userRole) => requiredRoles.includes(userRole));
  }
}

