function smart_sort_array($set, $order = 'ASC') {
    // Check if the input is valid
    if (!is_array($set) || count($set) <= 1) {
        return;
    }

    // Sort the array using usort function
    usort($set, function($a, $b) use ($order) {
        $result = $a['age'] - $b['age'];

        // Reverse the sort order if 'DESC' was provided
        if ($order === 'DESC') {
            $result *= -1;
        }

        return $result;
    });
}
