function smart_sort_array($set, $order = 'ASC') {
    // Check if set and order are valid
    if (!is_array($set) || count($set) <= 1) {
        return $set;
    }

    // Sort array using simple switching algorithm
    for ($i = 0; $i < count($set) - 1; $i++) {
        for ($j = 0; $j < count($set) - $i - 1; $j++) {
            if (($order == 'ASC' && $set[$j]['age'] > $set[$j+1]['age']) || ($order == 'DESC' && $set[$j]['age'] < $set[$j+1]['age'])) {
                // Swap elements if condition is met
                $temp = $set[$j];
                $set[$j] = $set[$j+1];
                $set[$j+1] = $temp;
            }
        }
    }

    return $set;
}
