```javascript
function findNestedEntry(obj, key) {
  let currentObj = obj;
  const keys = key.split("."); // Split the given key into an array of sub-keys

  // Iterate through each sub-key and check if it exists in the current object
  while (currentObj && keys.length > 0) {
    const subKey = keys.shift();
    currentObj = currentObj[subKey];
  }

  // If we reached an undefined property or ran out of keys, return null
  if (!currentObj || keys.length > 0) {
    return null;
  }

  // Otherwise, return the matched entry as an object with the original key and the found value
  return { key, value: currentObj };
}

// Example usage:
const myObject = {
  a: {
    b: "hello",
    c: { d: "world" },
  },
};

const result = findNestedEntry(myObject, "a.c.d"); // Returns { key: "a.c.d", value: "world" }
console.log(result);
```

