2. Create a method to validate and extract the username from the JWT token:

```csharp
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.IdentityModel.Tokens;
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;

public static string GetUsernameFromToken(string token)
{
    try
    {
        // Handler for JWT validation and claims extraction
        var tokenHandler = new JwtSecurityTokenHandler();

        // Validate the JWT token
        var key = Encoding.ASCII.GetBytes("Your_Secret_Key"); // Replace with your secret key
        SecurityToken validatedToken;

        if (!tokenHandler.CanReadToken(token)) throw new ArgumentException("Invalid JWT token.");

        var jwtToken = (JwtSecurityToken)tokenHandler.ReadToken(token);
        if (jwtToken == null || !jwtToken.ValidateSignature(key, validationParameters: null))
