        validatedToken = jwtToken;

        // Extract username claim value
        return validatedToken.Principal.FindFirst(ClaimTypes.Name).Value;
    }
    catch (Exception ex)
    {
        throw new ArgumentException("Error retrieving username from JWT.", ex);
    }
}
