 Here's a decorator for a Nest.js middleware function that checks the `NODE_ENV` environment variable and calls `next()` if it equals "true", or returns `false` otherwise:

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const NodeEnvChecker = () => {
  return createParamDecorator(
    (data: unknown, ctx: ExecutionContext) => {
      const req = ctx.switchToHttp().getRequest();
      const nodeEnv = process.env.NODE_ENV;

      if (nodeEnv === 'true') {
        return req.next(); // Call next middleware function
      } else {
        return false;
      }
    },
  );
};
```

You can use this decorator with middleware functions as follows:

