 To create a decorator for Nest.js middleware that checks the `NODE_ENV` variable and returns `next()` if it's equal to "true" or returns `false` otherwise, you can use the following code:

```typescript
import { createDecorator, ExecutionContext, Injectable } from '@nestjs/common';

@Injectable()
export class EnvCheckMiddleware {
  constructor() {}

  @createDecorator()
  static UseEnvChecker(condition: string): MethodDecorator {
    return (target: Object, key: string, descriptor: PropertyDescriptor) => {
      const originalMethod = descriptor.value;

      return {
        ...descriptor,
        value: function (...args: any[]) {
          if (process.env.NODE_ENV === condition) {
            return Reflect.apply(originalMethod, this, args).then((result) => Reflect.apply(next, this, args));
          } else {
            return Promise.resolve(false);
          }
        },
      };
    };
  }
}

const next = (req: Request, res: Response, next: Function) => next();

export function useEnvChecker(condition: string) {
  return CreateMiddleWare(EnvCheckMiddleware, 'UseEnvChecker', [condition]);
}
```

